// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";

/**
 * @title FileUploadVerifier
 * @notice Verifies signed file upload requests from a gRPC gateway service.
 *         The gRPC service forwards signed metadata for on-chain verification
 *         before committing file hashes to storage.
 */
contract FileUploadVerifier {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    struct UploadRequest {
        address uploader;
        bytes32 fileHash;
        uint256 fileSize;
        uint256 timestamp;
        string mimeType;
    }

    address public immutable trustedSigner;
    uint256 public constant SIGNATURE_VALIDITY_WINDOW = 300; // 5 minutes

    // Storage for verified uploads
    mapping(bytes32 => bool) public verifiedUploads;
    mapping(address => uint256) public uploadCount;
    mapping(address => uint256) public totalBytesUploaded;

    // Nonce tracking for replay protection
    mapping(address => uint256) public nonces;

    // Events
    event UploadVerified(address indexed uploader, bytes32 fileHash, uint256 fileSize);
    event NonceIncremented(address indexed user, uint256 newNonce);

    constructor(address _trustedSigner) {
        require(_trustedSigner != address(0), "Invalid signer");
        trustedSigner = _trustedSigner;
    }

    /**
     * @notice Computes the structured hash for an upload request
     * @dev Uses EIP-712-like structured hashing for domain separation
     */
    function _computeUploadHash(
        UploadRequest memory req,
        uint256 nonce
    ) internal view returns (bytes32) {
        return keccak256(
            abi.encodePacked(
                "\x19Ethereum Signed Message:\n32",
                keccak256(
                    abi.encode(
                        keccak256("UploadRequest(address uploader,bytes32 fileHash,uint256 fileSize,uint256 timestamp,string mimeType,uint256 nonce,uint256 chainId)"),
                        req.uploader,
                        req.fileHash,
                        req.fileSize,
                        req.timestamp,
                        keccak256(bytes(req.mimeType)),
                        nonce,
                        block.chainid
                    )
                )
            )
        );
    }

    /**
     * @notice Verifies a signed upload request and records it on-chain
     * @param req The upload request metadata
     * @param signature The ECDSA signature from the trusted gRPC signer
     * @param nonce The expected nonce for replay protection
     */
    function verifyAndRecordUpload(
        UploadRequest calldata req,
        bytes calldata signature,
        uint256 nonce
    ) external returns (bool) {
        // Validate timestamp is within acceptable window
        require(
            block.timestamp <= req.timestamp + SIGNATURE_VALIDITY_WINDOW,
            "Signature expired"
        );
        require(
            req.timestamp <= block.timestamp + 60,
            "Timestamp too far in future"
        );

        // Validate request parameters
        require(req.uploader != address(0), "Invalid uploader");
        require(req.fileSize > 0 && req.fileSize <= 100 * 1024 * 1024, "Invalid file size");
        require(req.fileHash != bytes32(0), "Invalid file hash");

        // Check nonce for replay protection
        require(nonce >= nonces[req.uploader], "Nonce too low");

        // Compute the message hash
        bytes32 messageHash = _computeUploadHash(req, nonce);

        // Recover signer and verify
        address recovered = messageHash.recover(signature);
        require(recovered == trustedSigner, "Invalid signature");

        // Check if this exact upload was already processed
        bytes32 uploadId = keccak256(abi.encode(req.fileHash, req.uploader));
        require(!verifiedUploads[uploadId], "Upload already verified");

        // Record the upload
        verifiedUploads[uploadId] = true;
        uploadCount[req.uploader]++;
        totalBytesUploaded[req.uploader] += req.fileSize;

        // Increment nonce
        nonces[req.uploader] = nonce + 1;

        emit UploadVerified(req.uploader, req.fileHash, req.fileSize);
        emit NonceIncremented(req.uploader, nonce + 1);

        return true;
    }

    /**
     * @notice Batch verify multiple uploads in a single transaction
     * @dev Used by the gRPC service for efficient batch processing
     */
    function batchVerifyUploads(
        UploadRequest[] calldata requests,
        bytes[] calldata signatures,
        uint256 startNonce
    ) external returns (uint256 successCount) {
        require(requests.length == signatures.length, "Length mismatch");
        require(requests.length <= 50, "Batch too large");

        for (uint256 i = 0; i < requests.length; i++) {
            // Each request in batch uses sequential nonce
            uint256 currentNonce = startNonce + i;

            // Skip if nonce already used (idempotent batch processing)
            if (currentNonce < nonces[requests[i].uploader]) {
                continue;
            }

            bytes32 messageHash = _computeUploadHash(requests[i], currentNonce);
            address recovered = messageHash.recover(signatures[i]);

            if (recovered != trustedSigner) {
                continue;
            }

            bytes32 uploadId = keccak256(abi.encode(requests[i].fileHash, requests[i].uploader));
            if (verifiedUploads[uploadId]) {
                continue;
            }

            // Validate timestamp
            if (block.timestamp > requests[i].timestamp + SIGNATURE_VALIDITY_WINDOW) {
                continue;
            }

            verifiedUploads[uploadId] = true;
            uploadCount[requests[i].uploader]++;
            totalBytesUploaded[requests[i].uploader] += requests[i].fileSize;
            nonces[requests[i].uploader] = currentNonce + 1;
            successCount++;

            emit UploadVerified(requests[i].uploader, requests[i].fileHash, requests[i].fileSize);
        }
    }

    /**
     * @notice Get the current nonce for a user
     */
    function getCurrentNonce(address user) external view returns (uint256) {
        return nonces[user];
    }
}
